const d = $input.first().json;
const files = d.files || [];
const names = files.map(f => f.filename.replace(/\\/g, '/'));
const py = files.filter(f => f.extension === 'py' && !f.binary);

const has = n => names.some(x => x === n || x.endsWith('/' + n));
const imports = lib => {
  const escaped = lib.replace(/\./g, '\\.');
  return py.some(f => new RegExp('(^|\n)\\s*(from\\s+' + escaped + '|import\\s+' + escaped + ')', 'm').test(f.content || ''));
};

let track = 'A';
let type = 'python_project';
let framework = 'Python';
let entrypoint = null;
let start_cmd = null;
let port = null;
let browser_runnable = false;
let domain = 'general_python';

// Check for n8n workflow JSON first (Track B)
const workflowFile = files.find(f => f.filename === 'workflow.json' || f.filename.endsWith('/workflow.json'));

if (workflowFile && !workflowFile.binary) {
  try {
    const w = JSON.parse(workflowFile.content);
    if (Array.isArray(w.nodes) && w.connections && typeof w.connections === 'object') {
      track = 'B';
      type = 'n8n_workflow';
      framework = 'n8n';
      entrypoint = workflowFile.filename;
    }
  } catch {}
}

// Track A: Python project detection
if (track === 'A') {
  if (has('app.py') && imports('streamlit')) {
    type = 'streamlit';
    framework = 'Streamlit';
    entrypoint = 'app.py';
    start_cmd = 'streamlit run app.py --server.headless true --server.address 0.0.0.0 --server.port 8501';
    port = 8501;
    browser_runnable = true;
  } else if (imports('fastapi')) {
    type = 'fastapi';
    framework = 'FastAPI';
    entrypoint = has('main.py') ? 'main.py' : 'app.py';
    start_cmd = 'uvicorn main:app --host 0.0.0.0 --port 8000';
    port = 8000;
    browser_runnable = true;
  } else if (has('app.py') && imports('flask')) {
    type = 'flask';
    framework = 'Flask';
    entrypoint = 'app.py';
    start_cmd = 'python app.py';
    port = 5000;
    browser_runnable = true;
  } else if (imports('gradio')) {
    type = 'gradio';
    framework = 'Gradio';
    entrypoint = py.find(f => /app|main/i.test(f.filename))?.filename || py[0]?.filename;
    start_cmd = 'python ' + (py.find(f => /app|main/i.test(f.filename))?.filename || py[0]?.filename || 'app.py');
    port = 7860;
    browser_runnable = true;
  } else if (has('manage.py')) {
    type = 'django';
    framework = 'Django';
    entrypoint = 'manage.py';
    start_cmd = 'python manage.py runserver 0.0.0.0:8000';
    port = 8000;
    browser_runnable = true;
  } else if (has('index.html')) {
    type = 'static_web';
    framework = 'HTML/CSS/JS';
    entrypoint = 'index.html';
    start_cmd = 'python -m http.server 8000 --bind 0.0.0.0';
    port = 8000;
    browser_runnable = true;
  }

  // Domain detection: orthogonal to runtime
  if (imports('langchain') || imports('langgraph') || imports('qdrant_client') || imports('chromadb') || imports('faiss')) {
    domain = 'rag_or_agent';
  } else if (imports('openai') || imports('anthropic') || imports('google.generativeai')) {
    domain = 'llm_application';
  }
}

return {
  ...d,
  detection: {
    track,
    type,
    framework,
    domain,
    entrypoint,
    start_cmd,
    port,
    browser_runnable
  }
};

const d = $input.first().json;
const candidates = [];

// FIX: .env files ARE scanned here — they are excluded from publishing later,
// not before scanning. This ensures we harvest real secret variable names.

const patterns = [
  { name: 'Google API Key',      regex: /AIza[A-Za-z0-9_-]{35}/g },
  { name: 'GitHub Token',        regex: /(?:ghp|gho|github_pat)_[A-Za-z0-9_]{20,}/g },
  { name: 'OpenAI Key',          regex: /sk-[A-Za-z0-9]{32,}/g },
  { name: 'Anthropic Key',       regex: /sk-ant-[A-Za-z0-9_-]{32,}/g },
  { name: 'HuggingFace Token',   regex: /hf_[A-Za-z0-9]{32,}/g },
  { name: 'AWS Access Key',      regex: /AKIA[A-Z0-9]{16}/g },
  { name: 'Bearer Token',        regex: /Bearer\s+[A-Za-z0-9_.=-]{20,}/gi },
  { name: 'Database URL',        regex: /(?:postgres(?:ql)?|mongodb(?:\+srv)?|mysql|redis):\/\/[^\s]+:[^\s]+@/gi },
  { name: 'API Key Assignment',  regex: /(?:api[_-]?key|apikey)\s*[=:]\s*['"][^'"]{12,}['"]/gi },
  { name: 'Secret Assignment',   regex: /(?:secret[_-]?key|client[_-]?secret)\s*[=:]\s*['"][^'"]{12,}['"]/gi },
  { name: 'Password Assignment', regex: /(?:password|passwd|pwd)\s*[=:]\s*['"][^'"]{8,}['"]/gi }
];

for (const file of d.files || []) {
  if (file.binary || !file.content || file.content === '[binary file]') continue;

  const lines = file.content.split('\n');

  for (const pattern of patterns) {
    // Always create a fresh regex to reset lastIndex
    const regex = new RegExp(pattern.regex.source, pattern.regex.flags);
    let match;

    while ((match = regex.exec(file.content)) !== null) {
      const lineNum = (file.content.slice(0, match.index).match(/\n/g) || []).length + 1;

      candidates.push({
        index: candidates.length,  // stable global index — Gemini references this
        file: file.filename,
        line: lineNum,
        type: pattern.name,
        match: match[0].slice(0, 150),
        line_content: (lines[lineNum - 1] || '').trim()
      });
    }
  }
}

return {
  ...d,
  security_scan_pass1: {
    flagged_count: candidates.length,
    flagged_items: candidates
  }
};

const d = $input.first().json;
const flagged = d.security_scan_pass1.flagged_items || [];

// Only send file content snippets, not entire files, to limit token usage
const fileSnippets = {};
for (const item of flagged) {
  if (!fileSnippets[item.file]) {
    const file = d.files.find(f => f.filename === item.file);
    if (file && !file.binary) {
      // Send first 2000 chars of each flagged file for context
      fileSnippets[item.file] = (file.content || '').slice(0, 2000);
    }
  }
}

const prompt = `You are a security engineer reviewing a software project before it is published to GitHub.

Project: ${d.project_name}
Detected framework: ${d.detection.framework}
Files in project: ${JSON.stringify(d.file_names)}

Pass 1 regex scan flagged these ${flagged.length} candidates:
${JSON.stringify(flagged, null, 2)}

File context snippets (for the files containing flags):
${JSON.stringify(fileSnippets, null, 2)}

For each candidate, determine:
1. Is this a real secret (is_real: true) or a placeholder/example/test value (is_real: false)?
2. If real, what ENV VAR name should replace it? (e.g. GEMINI_API_KEY, OPENAI_API_KEY)

IMPORTANT: The index in your response MUST match the index from the flagged candidates array above.
Do NOT renumber. Reference the original indexes exactly.

Return ONLY valid JSON in this exact format — no explanation, no markdown:
{
  "summary": "2-3 sentence factual description of what this project does",
  "tech_stack": ["list", "of", "technologies", "detected"],
  "confirmed_secrets": [
    {"index": 0, "is_real": true, "placeholder": "GEMINI_API_KEY"},
    {"index": 1, "is_real": false, "placeholder": ""}
  ]
}`;

return {
  ...d,
  gemini_security_prompt: prompt
};

const d = $input.first().json;
const remaining = [];

// Same high-confidence patterns as Pass 1 — these should never survive sanitization
const patterns = [
  /AIza[A-Za-z0-9_-]{35}/g,
  /(?:ghp|gho|github_pat)_[A-Za-z0-9_]{20,}/g,
  /sk-[A-Za-z0-9]{32,}/g,
  /sk-ant-[A-Za-z0-9_-]{32,}/g,
  /hf_[A-Za-z0-9]{32,}/g,
  /AKIA[A-Z0-9]{16}/g,
  /Bearer\s+[A-Za-z0-9_.=-]{20,}/gi,
  /(?:postgres(?:ql)?|mongodb(?:\+srv)?|mysql|redis):\/\/[^\s]+:[^\s]+@/gi
];

for (const file of d.files || []) {
  // Skip .env.example — placeholders intentionally match some patterns
  if (file.filename === '.env.example') continue;
  if (file.binary || !file.content || file.content === '[binary file]') continue;

  for (const pattern of patterns) {
    const regex = new RegExp(pattern.source, pattern.flags);
    let match;
    while ((match = regex.exec(file.content)) !== null) {
      remaining.push({
        file: file.filename,
        match: match[0].slice(0, 100)
      });
    }
  }
}

return {
  ...d,
  security_scan_pass2: {
    passed: remaining.length === 0,
    remaining_secrets_count: remaining.length,
    remaining_secrets: remaining
  }
};

const d = $input.first().json;
// This node receives already-Gemini-reviewed, already-sanitized files from the main pipeline.
// It adds n8n-specific deep sanitization ON TOP of what was already done.

const workflowFile = d.files.find(f => f.filename === 'workflow.json' || f.filename.endsWith('/workflow.json'));

if (!workflowFile) throw new Error('workflow.json not found after sanitization stage.');

let workflow;
try {
  workflow = JSON.parse(workflowFile.content);
} catch(e) {
  throw new Error('workflow.json is not valid JSON: ' + e.message);
}

const replaced = [];

// FIX: Do NOT treat url/baseUrl/webhookUrl/endpoint as secrets.
// Only target fields that are semantically credential-like.
const SECRET_KEYS = /^(api[_-]?key|apiKey|accessToken|refreshToken|password|passwd|secret|secretKey|clientSecret|authorization|bearerToken|privateKey|authToken|credential)$/i;

// FIX: Skip values that are already placeholders or clearly not real secrets
const isAlreadyPlaceholder = v => /\{\{[A-Z0-9_]+\}\}|YOUR_|REPLACE_|<[^>]+>|^example$/i.test(v);

function sanitizeParams(value, nodeName, keyName) {
  if (Array.isArray(value)) return value.map(v => sanitizeParams(v, nodeName, keyName));
  if (value === null || typeof value !== 'object') {
    if (typeof value === 'string' && SECRET_KEYS.test(keyName) && value.length >= 8 && !isAlreadyPlaceholder(value)) {
      const envName = keyName.toUpperCase().replace(/[^A-Z0-9]/g, '_');
      replaced.push({ node: nodeName, key: keyName, placeholder: envName });
      return `{{${envName}}}`;
    }
    return value;
  }
  const out = {};
  for (const [key, val] of Object.entries(value)) {
    if (key === 'credentials') continue; // Always strip credentials block
    out[key] = sanitizeParams(val, nodeName, key);
  }
  return out;
}

const sanitizedWorkflow = {
  ...workflow,
  nodes: (workflow.nodes || []).map(node => ({
    ...node,
    credentials: {}, // Always wipe credentials
    parameters: sanitizeParams(node.parameters || {}, node.name || node.id || 'unknown_node')
  }))
};

// Remove top-level credentials if present
delete sanitizedWorkflow.credentials;

// Extract node structure for diagram generation (use stable IDs)
const workflow_structure = {
  nodes: (workflow.nodes || []).map(n => ({
    id: n.id,      // Use stable ID, not just name (names can be duplicated)
    name: n.name,
    type: n.type,
    position: n.position
  })),
  connections: workflow.connections || {}
};

// Replace workflow.json content with sanitized version
const files = d.files.map(f => {
  if (f.filename === workflowFile.filename) {
    return { ...f, content: JSON.stringify(sanitizedWorkflow, null, 2) };
  }
  return f;
});

// Merge sanitization counts with what the main pipeline already did
const prevReplaced = d.sanitization?.secrets_replaced || 0;

return {
  ...d,
  files,
  workflow_structure,
  sanitization: {
    secrets_replaced: prevReplaced + replaced.length,
    replacements: [...(d.sanitization?.replacements || []), ...replaced],
    env_vars_generated: d.sanitization?.env_vars_generated || 0
  }
};

const d = $input.first().json;

if (!d.workflow_structure) {
  return { ...d, has_visual: false, screenshot_status: 'skipped_no_ui', diagram_svg: null };
}

const nodes = d.workflow_structure.nodes || [];
const connections = d.workflow_structure.connections || {};

if (!nodes.length) {
  return { ...d, has_visual: false, screenshot_status: 'skipped_no_ui', diagram_svg: null };
}

// Layout: use actual n8n positions where available
const BOX_W = 190;
const BOX_H = 60;
const PADDING = 60;

// Compute bounding box of all node positions
let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
nodes.forEach((node, i) => {
  const p = node.position || [i * 230, 100];
  const x = Number(p[0]);
  const y = Number(p[1]);
  minX = Math.min(minX, x);
  minY = Math.min(minY, y);
  maxX = Math.max(maxX, x + BOX_W);
  maxY = Math.max(maxY, y + BOX_H);
});

// Normalize so all positions start from PADDING
const offsetX = PADDING - minX;
const offsetY = PADDING + 60 - minY; // +60 for title

const svgWidth = Math.max(1200, maxX - minX + BOX_W + PADDING * 2);
const svgHeight = Math.max(600, maxY - minY + BOX_H + PADDING * 2 + 60);

// Build position map by node NAME (connections reference by name)
const posMap = {};
nodes.forEach((node, i) => {
  const p = node.position || [i * 230, 100];
  posMap[node.name] = {
    x: Number(p[0]) + offsetX,
    y: Number(p[1]) + offsetY,
    id: node.id
  };
});

const esc = s => String(s || '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Draw arrows
const arrows = [];
for (const [sourceName, outputs] of Object.entries(connections)) {
  const src = posMap[sourceName];
  if (!src) continue;
  for (const groups of Object.values(outputs || {})) {
    for (const group of (groups || [])) {
      for (const target of (group || [])) {
        const dst = posMap[target.node];
        if (!dst) continue;
        const x1 = src.x + BOX_W;
        const y1 = src.y + BOX_H / 2;
        const x2 = dst.x;
        const y2 = dst.y + BOX_H / 2;
        const mx = (x1 + x2) / 2;
        arrows.push(`<path d="M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2},${y2}" fill="none" stroke="#64748b" stroke-width="1.5" marker-end="url(#arrow)"/>`);
      }
    }
  }
}

// Draw node boxes
const boxes = nodes.map(node => {
  const p = posMap[node.name];
  const label = esc(node.name).slice(0, 26);
  const sublabel = esc((node.type || '').split('.').pop()).slice(0, 30);
  return [
    `<rect x="${p.x}" y="${p.y}" width="${BOX_W}" height="${BOX_H}" rx="8" fill="#1e293b" stroke="#475569" stroke-width="1"/>`,
    `<text x="${p.x + BOX_W / 2}" y="${p.y + 22}" text-anchor="middle" fill="#f1f5f9" font-size="11" font-weight="600" font-family="Arial,sans-serif">${label}</text>`,
    `<text x="${p.x + BOX_W / 2}" y="${p.y + 40}" text-anchor="middle" fill="#94a3b8" font-size="9" font-family="Arial,sans-serif">${sublabel}</text>`
  ].join('');
}).join('');

const svg = [
  `<svg xmlns="http://www.w3.org/2000/svg" width="${svgWidth}" height="${svgHeight}">`,
  `<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L8,3 z" fill="#64748b"/></marker></defs>`,
  `<rect width="100%" height="100%" fill="#0f172a"/>`,
  `<text x="30" y="40" fill="#f8fafc" font-size="18" font-weight="700" font-family="Arial,sans-serif">${esc(d.project_name)} — n8n Workflow Diagram</text>`,
  `<text x="30" y="58" fill="#64748b" font-size="11" font-family="Arial,sans-serif">${nodes.length} nodes</text>`,
  ...arrows,
  boxes,
  `</svg>`
].join('');

return {
  ...d,
  diagram_svg: svg,
  has_visual: true,
  screenshot_status: 'workflow_diagram_generated'
};

const d = $input.first().json;

const FILE_CONTENT_LIMIT = 800;
const fileContextLines = [];

for (const file of (d.files || [])) {
  if (file.binary || file.content === '[binary file]') continue;
  if (file.filename === '.env.example') continue;
  const snippet = (file.content || '').slice(0, FILE_CONTENT_LIMIT);
  fileContextLines.push(`### ${file.filename}\n${snippet}${snippet.length >= FILE_CONTENT_LIMIT ? '\n... [truncated]' : ''}`);
  if (fileContextLines.join('').length > 8000) break;
}

const envVars = d.sanitization?.replacements?.map(r => r.placeholder) || [];

const prompt = `Create a highly professional, visually structured README.md for this project. Use ONLY the information provided below — do not invent anything.

Project Name: ${d.project_name}
Project Type: ${d.detection?.type}
Framework: ${d.detection?.framework}
Domain: ${d.detection?.domain}
Short Description: ${d.short_description || 'Not provided'}
AI Analysis: ${d.gemini_analysis?.summary || 'Not available'}
Tech Stack: ${JSON.stringify(d.gemini_analysis?.tech_stack || [])}
Entrypoint: ${d.detection?.entrypoint || 'Not detected'}
Start Command: ${d.detection?.start_cmd || 'Not detected'}
Port: ${d.detection?.port || 'N/A'}
Visual/Screenshot: ${d.screenshot_status}
Environment Variables Required: ${envVars.length ? envVars.join(', ') : 'None detected'}

File structure:
${(d.file_names || []).join('\n')}

File content snippets:
${fileContextLines.join('\n\n')}

STRUCTURE — include ALL of these sections in this exact order:

1. PROJECT TITLE & BADGES
   - Large title with a relevant emoji
   - Badges (use shields.io): Python version or framework badge, License badge, Status badge (Active)
   - One-line tagline under the title

2. OVERVIEW
   - 2-3 sentence description of what this project does
   - Use a blockquote (>) for the main value proposition

3. FEATURES
   - Use a markdown table with columns: Feature | Description | Status
   - Each feature gets a checkmark emoji ✅ in Status column
   - Extract features ONLY from the actual code provided

4. TECH STACK
   - Use a markdown table with columns: Technology | Purpose | Version
   - Only include technologies visible in the code

5. PROJECT STRUCTURE
   - Use a code block with tree structure showing all files
   - Add inline comments after each file explaining what it does

6. GETTING STARTED
   ### Prerequisites
   - Bullet list of requirements (Python version, pip, etc.)

   ### Installation
   - Numbered steps with code blocks for each command

   ### Environment Variables
   - If env vars exist: markdown table with columns: Variable | Description | Required
   - If none: say "No environment variables required"

   ### Running the App
   - Code block with the exact start command

7. VISUAL PREVIEW
   - Only include if screenshot_status is 'captured' or 'workflow_diagram_generated'
   - Add: ![App Screenshot](assets/screenshot.png) or ![Workflow](assets/workflow-diagram.svg)
   - Add a caption under the image

8. HOW IT WORKS
   - Numbered list explaining the workflow/pipeline steps
   - Extract ONLY from actual code — do not invent steps

9. SECURITY
   - Mention that secrets are handled via environment variables
   - Add a note about .env.example

10. LICENSE
    - MIT License section
    - Exact text: "This project is licensed under the MIT License."

11. AUTHOR
    - Name: YOUR_NAME
    - Title: YOUR_TITLE
    - GitHub: YOUR_GITHUB_URL
    - LinkedIn: YOUR_LINKEDIN_URL

FORMATTING RULES:
- Use emojis for every section heading (🚀 Overview, ✨ Features, 🛠️ Tech Stack, 📁 Structure, 🚀 Getting Started, 🖼️ Preview, ⚙️ How It Works, 🔒 Security, 📄 License, 👤 Author)
- Use markdown tables wherever data has multiple attributes
- Use code blocks for all commands
- Use horizontal rules (---) between major sections
- Make it look like a top 1% open source README
- Return raw Markdown only — no code fences around the entire response
- Do NOT invent features, metrics, users, or capabilities not visible in the code`;

return {
  ...d,
  readme_prompt: prompt
};

const d = $input.first().json;
const token = "YOUR_GITHUB_TOKEN_HERE";

const repoName = (d.project_name || 'untitled-project')
  .trim()
  .replace(/[^a-zA-Z0-9-\s]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '')
  .slice(0, 100) || 'Untitled-Project';

// n8n 2.33.5 mein built-in helpers check karo
const helpers = $execution?.customData || {};

// Sirf data prepare karo — actual API call HTTP Request node karega
return {
  ...d,
  github_repo_name: repoName,
  github_payload: {
    name: repoName,
    description: (d.github_metadata?.repo_description || d.project_name || '').slice(0, 350),
    private: d.github_visibility === 'private',
    auto_init: false,
    has_issues: true,
    has_projects: false,
    has_wiki: false
  },
  github_token: token
};

const screenshotData = $input.first().json;
const pipelineData = $('Sanitization').first().json;

return {
  ...pipelineData,
  screenshot_b64: screenshotData.screenshot || screenshotData.screenshot_b64 || null,
  screenshot_taken: !!(screenshotData.screenshot || screenshotData.screenshot_b64),
  screenshot_public_url: screenshotData.public_url || null,
  has_visual: !!(screenshotData.screenshot || screenshotData.screenshot_b64),
  screenshot_status: (screenshotData.screenshot || screenshotData.screenshot_b64) ? 'captured' : 'failed'
};

const response = $input.first().json;
const original = $('Prepare AI Security Review1').first().json;

// Groq format
const raw = response.choices?.[0]?.message?.content || '{}';
let ai;

try {
  const cleaned = raw.replace(/^```json\n?|\n?```$/g, '').trim();
  ai = JSON.parse(cleaned);
} catch {
  ai = { summary: '', tech_stack: [], confirmed_secrets: [] };
}

const flagged = original.security_scan_pass1.flagged_items || [];
const confirmed = (ai.confirmed_secrets || []).filter(x => x.is_real === true);

let files = original.files.map(f => ({ ...f }));
const replacements = [];
const envVars = {};

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

for (const secret of confirmed) {
  const candidate = flagged.find(x => x.index === secret.index);
  if (!candidate) continue;

  const envName = String(secret.placeholder || 'SECRET')
    .toUpperCase()
    .replace(/[^A-Z0-9_]/g, '_');

  const placeholder = `{{${envName}}}`;
  envVars[envName] = `your_${envName.toLowerCase()}_here`;

  files = files.map(file => {
    if (file.filename !== candidate.file) return file;
    return {
      ...file,
      content: file.content.replace(new RegExp(escapeRegex(candidate.match), 'g'), placeholder)
    };
  });

  replacements.push({
    file: candidate.file,
    line: candidate.line,
    type: candidate.type,
    placeholder: envName
  });
}

const envFile = files.find(f => f.is_env_file && !f.binary);
if (envFile) {
  for (const line of (envFile.content || '').split('\n')) {
    const match = line.match(/^([A-Z0-9_]+)=/);
    if (match && !envVars[match[1]]) {
      envVars[match[1]] = `your_${match[1].toLowerCase()}_here`;
    }
  }
}

files = files.filter(f => !f.is_env_file);

const envExample = Object.entries(envVars)
  .map(([key, value]) => `${key}=${value}`)
  .join('\n');

if (envExample) {
  files.push({
    filename: '.env.example',
    content: envExample,
    extension: 'example',
    binary: false,
    is_env_file: false
  });
}

return {
  ...original,
  files,
  gemini_analysis: {
    summary: ai.summary || '',
    tech_stack: ai.tech_stack || []
  },
  sanitization: {
    secrets_replaced: replacements.length,
    replacements,
