const input = $input.first();
const form = input.json || {};
const binary = input.binary || {};

const IGNORED = [
  'node_modules/', '.git/', '__pycache__/',
  '.venv/', 'venv/', '.pyc', '.pyo', 'Thumbs.db', '.DS_Store', '__MACOSX/'
];

const BINARY_EXT = ['png','jpg','jpeg','gif','svg','ico','pdf','exe','dll','so','whl','bin','dat'];
const TEXT_EXT = [
  'py','js','ts','jsx','tsx','html','css','json','yaml','yml',
  'md','txt','env','sh','bat','cfg','ini','toml','xml','csv',
  'sql','r','rb','php','java','cpp','c','h','go','rs','swift',
  'kt','scala','lua','pl','ps1','gitignore','example','lock',
  'dockerfile','prettierrc','eslintrc','babelrc'
];

const files = [];
const seenFiles = new Set();
const BINARY_KEYS = Object.keys(binary);

for (let i = 0; i < BINARY_KEYS.length; i++) {
  const key = BINARY_KEYS[i];
  const singleFile = binary[key];
  if (!singleFile || !singleFile.fileName) continue;

  const filename = singleFile.fileName.replace(/\\/g, '/');
  if (IGNORED.some(p => filename.includes(p))) continue;
  if (seenFiles.has(filename)) continue;
  seenFiles.add(filename);

  const ext = filename.includes('.') ? filename.split('.').pop().toLowerCase() : '';
  const mimeType = singleFile.mimeType || '';
  const isForcedBinary = BINARY_EXT.includes(ext);
  const isZip = ext === 'zip';

  let content = '';
  let isBinary = isForcedBinary;

  if (!isZip && !isForcedBinary) {
    try {
      // itemIndex 0 use karo — form trigger pe sirf ek item hota hai
      const buffer = await this.helpers.getBinaryDataBuffer(0, key);
      const text = buffer.toString('utf8');

      if (text.includes('\u0000')) {
        isBinary = true;
        content = '[binary file]';
      } else {
        content = text;
      }
    } catch(e) {
      isBinary = true;
      content = '[binary file]';
    }
  }

  files.push({
    filename,
    content: isBinary ? '[binary file]' : content,
    extension: ext,
    binary: isBinary,
    is_zip: isZip,
    is_env_file: filename === '.env' || filename.endsWith('/.env')
  });
}

if (!files.length) {
  throw new Error('No files received. Keys: ' + JSON.stringify(BINARY_KEYS));
}

return {
  project_name: (form['Project Name'] || 'untitled-project').trim(),
  github_visibility: (form['GitHub Visibility'] || 'public').toLowerCase(),
  linkedin_tone: form['LinkedIn Tone'] || 'Professional',
  user_email: (form['Email'] || '').trim().toLowerCase(),
  short_description: (form['Short Description'] || '').trim(),
  files,
  file_names: files.map(f => f.filename),
  file_count: files.length,
  has_zip: files.some(f => f.is_zip)
};
